from datetime import date, datetime
from typing import Literal, Optional

from pydantic import BaseModel, Field, field_validator


class Mood(BaseModel):
    value: Literal["happy", "neutral", "sad", "stressed", "excited", "anxious", "calm", "inspired", "tired"]
    label: str

    @classmethod
    def defaults(cls) -> list["Mood"]:
        return [
            cls(value="happy", label="Happy"),
            cls(value="neutral", label="Neutral"),
            cls(value="sad", label="Sad"),
            cls(value="stressed", label="Stressed"),
            cls(value="excited", label="Excited"),
            cls(value="anxious", label="Anxious"),
            cls(value="calm", label="Calm"),
            cls(value="inspired", label="Inspired"),
            cls(value="tired", label="Tired"),
        ]

    @classmethod
    def from_value(cls, value: str) -> "Mood":
        return cls(value=value, label=value.capitalize())

    @field_validator("label", mode="before")
    @classmethod
    def validate_label(cls, v: str, info) -> str:
        if not v or not v.strip():
            raise ValueError("label must not be empty")
        return v.strip()


class Weather(BaseModel):
    value: Literal["sunny", "cloudy", "rainy", "snowy", "stormy", "windy", "foggy"]
    label: str

    @classmethod
    def defaults(cls) -> list["Weather"]:
        return [
            cls(value="sunny", label="Sunny"),
            cls(value="cloudy", label="Cloudy"),
            cls(value="rainy", label="Rainy"),
            cls(value="snowy", label="Snowy"),
            cls(value="stormy", label="Stormy"),
            cls(value="windy", label="Windy"),
            cls(value="foggy", label="Foggy"),
        ]

    @classmethod
    def from_value(cls, value: str) -> "Weather":
        return cls(value=value, label=value.capitalize())

    @field_validator("label", mode="before")
    @classmethod
    def validate_label(cls, v: str, info) -> str:
        if not v or not v.strip():
            raise ValueError("label must not be empty")
        return v.strip()


class Entry(BaseModel):
    id: Optional[int] = None
    date: date
    mood: Mood
    weather: Weather
    notes: str = ""
    created_at: datetime = Field(default_factory=datetime.now)
    updated_at: datetime = Field(default_factory=datetime.now)

    @field_validator("notes", mode="before")
    @classmethod
    def validate_notes(cls, v: str) -> str:
        return v.strip() if v else ""

    @field_validator("date", mode="before")
    @classmethod
    def validate_date(cls, v) -> date:
        if isinstance(v, str):
            return date.fromisoformat(v)
        return v

    @classmethod
    def defaults(cls) -> "Entry":
        return cls(
            date=date.today(),
            mood=Mood.from_value("neutral"),
            weather=Weather.from_value("sunny"),
            notes="",
        )

    def refresh_updated_at(self) -> None:
        self.updated_at = datetime.now()
